// Server side of the A2A core: a fetch-style handler for GET
// /.well-known/agent-card.json plus the JSON-RPC methods in INTERFACES.md.
// Tasks live in memory with full history; the server records work but never
// runs it. Session ownership stays with the host plugin: onMessage notifies it
// of each inbound message, onCancel asks it to stop whatever runs for that
// taskId, and appendMessage/setStatus let it write replies and transitions
// back onto the task so open message/stream subscribers see them.

import { z } from "zod";
import { A2AError, ErrorCode, type SendConfiguration } from "./client";
import {
  AgentCardSchema,
  MessageSchema,
  TaskStateSchema,
  type AgentCard,
  type Artifact,
  type Message,
  type StreamEvent,
  type Task,
  type TaskList,
  type TaskState,
  type TaskStatus,
} from "./types";

const TERMINAL_STATES = new Set<TaskState>([
  "TASK_STATE_COMPLETED",
  "TASK_STATE_FAILED",
  "TASK_STATE_CANCELED",
  "TASK_STATE_REJECTED",
]);

// Interrupted states are not terminal: the peer may still reply or cancel.
const INTERRUPTED_STATES = new Set<TaskState>([
  "TASK_STATE_INPUT_REQUIRED",
  "TASK_STATE_AUTH_REQUIRED",
]);

const STREAM_END_STATES = new Set<TaskState>([...TERMINAL_STATES, ...INTERRUPTED_STATES]);

const DEFAULT_PAGE_SIZE = 50;
const MAX_PAGE_SIZE = 200;

// Optional request header a peer can use to self-identify; the value is
// recorded on the task as metadata.peerId for the host's session records.
export const A2A_PEER_HEADER = "x-a2a-peer";

type RpcId = string | number | null;

const RpcRequestSchema = z.object({
  jsonrpc: z.literal("2.0"),
  id: z.union([z.string(), z.number(), z.null()]).default(null),
  method: z.string(),
  params: z.unknown().optional(),
});

const ConfigurationSchema = z.object({
  acceptedOutputModes: z.array(z.string()).optional(),
  historyLength: z.number().int().nonnegative().optional(),
  returnImmediately: z.boolean().optional(),
});

export const SendMessageParamsSchema = z.object({
  message: MessageSchema,
  configuration: ConfigurationSchema.optional(),
});
export type SendMessageParams = z.infer<typeof SendMessageParamsSchema>;

export const TaskGetParamsSchema = z.object({
  id: z.string().min(1),
  historyLength: z.number().int().nonnegative().optional(),
});
export type TaskGetParams = z.infer<typeof TaskGetParamsSchema>;

export const TaskListParamsSchema = z.object({
  contextId: z.string().optional(),
  status: TaskStateSchema.optional(),
  pageSize: z.number().int().positive().optional(),
  pageToken: z.string().optional(),
  historyLength: z.number().int().nonnegative().optional(),
});
export type TaskListParams = z.infer<typeof TaskListParamsSchema>;

export const TaskCancelParamsSchema = z.object({
  id: z.string().min(1),
});
export type TaskCancelParams = z.infer<typeof TaskCancelParamsSchema>;

export interface A2AServerOptions {
  // A getter defers card construction until the host knows its bound port.
  card: AgentCard | (() => AgentCard);
  // Notification-only hook: fired after each inbound message is recorded, via
  // both message/send and message/stream. The host owns any async session work.
  onMessage?: (task: Task, message: Message) => void;
  // Awaited by tasks/cancel so the host can stop the session mapped to taskId.
  onCancel?: (task: Task) => void | Promise<void>;
}

export class A2AServer {
  private readonly options: A2AServerOptions;
  private readonly tasks = new Map<string, Task>();
  private readonly listeners = new Map<string, Set<(event: StreamEvent) => void>>();

  constructor(options: A2AServerOptions) {
    this.options = options;
  }

  // `peer` is a caller-supplied identity fallback (e.g. the socket address);
  // an explicit x-a2a-peer header always wins over it.
  async fetch(request: Request, peer?: string): Promise<Response> {
    const url = new URL(request.url);
    if (request.method === "GET" && url.pathname === "/.well-known/agent-card.json")
      return this.agentCard();
    if (request.method !== "POST") return new Response("Not Found", { status: 404 });
    return this.rpc(request, request.headers.get(A2A_PEER_HEADER) ?? peer);
  }

  sendMessage(message: Message, configuration?: SendConfiguration, peer?: string): Task {
    const task = this.record(message, peer);
    this.options.onMessage?.(task, message);
    return view(task, configuration?.historyLength);
  }

  getTask(id: string, historyLength?: number): Task {
    return view(this.require(id), historyLength);
  }

  listTasks(filter: TaskListParams = {}): TaskList {
    const matching = [...this.tasks.values()].filter(
      (task) =>
        (filter.contextId === undefined || task.contextId === filter.contextId) &&
        (filter.status === undefined || task.status.state === filter.status),
    );
    const pageSize = Math.min(filter.pageSize ?? DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE);
    const offset = pageOffset(filter.pageToken);
    const page = matching.slice(offset, offset + pageSize);
    const next = offset + page.length;
    return {
      tasks: page.map((task) => view(task, filter.historyLength)),
      nextPageToken: next < matching.length ? String(next) : "",
      pageSize,
      totalSize: matching.length,
    };
  }

  async cancelTask(id: string): Promise<Task> {
    const task = this.require(id);
    if (TERMINAL_STATES.has(task.status.state))
      throw new A2AError(
        ErrorCode.TASK_NOT_CANCELLABLE,
        `Task "${id}" is already ${task.status.state}.`,
      );
    task.status = { state: "TASK_STATE_CANCELED", timestamp: timestamp() };
    try {
      await this.options.onCancel?.(task);
    } catch {
      // Host cleanup (aborting the session for this task) is best-effort: the
      // task is canceled regardless, so the cancel event and response still
      // reach the caller.
    } finally {
      this.emit(task, statusEvent(task));
    }
    return task;
  }

  // Host-facing recorders: the plugin's session runner writes its reply and
  // transitions back onto the task through these so history, tasks/get, and
  // open streams all observe the same state.

  appendMessage(taskId: string, message: Message): Task {
    const task = this.require(taskId);
    const stored = linked(message, task);
    task.history = [...(task.history ?? []), stored];
    this.emit(task, stored);
    return task;
  }

  setStatus(taskId: string, status: TaskStatus): Task {
    const task = this.require(taskId);
    task.status = { ...status, timestamp: status.timestamp ?? timestamp() };
    this.emit(task, statusEvent(task));
    return task;
  }

  appendArtifact(taskId: string, artifact: Artifact): Task {
    const task = this.require(taskId);
    task.artifacts = [...(task.artifacts ?? []), artifact];
    this.emit(task, { taskId: task.id, contextId: task.contextId ?? "", artifact });
    return task;
  }

  private agentCard(): Response {
    const card = typeof this.options.card === "function" ? this.options.card() : this.options.card;
    const parsed = AgentCardSchema.safeParse(card);
    if (!parsed.success) return new Response("Invalid agent card", { status: 500 });
    return Response.json(parsed.data);
  }

  private async rpc(request: Request, peer?: string): Promise<Response> {
    const body: unknown = await request.json().catch(() => undefined);
    if (body === undefined)
      return rpcError(null, ErrorCode.PARSE_ERROR, "Request body is not valid JSON.");
    const parsed = RpcRequestSchema.safeParse(body);
    if (!parsed.success)
      return rpcError(null, ErrorCode.INVALID_REQUEST, "Invalid JSON-RPC request.");
    const { id, method, params } = parsed.data;
    switch (method) {
      case "message/send":
        return this.invoke(id, params, SendMessageParamsSchema, (p) =>
          this.sendMessage(p.message, p.configuration, peer),
        );
      case "tasks/get":
        return this.invoke(id, params, TaskGetParamsSchema, (p) =>
          this.getTask(p.id, p.historyLength),
        );
      case "tasks/list":
        return this.invoke(id, params, TaskListParamsSchema, (p) => this.listTasks(p));
      case "tasks/cancel":
        return this.invoke(id, params, TaskCancelParamsSchema, (p) => this.cancelTask(p.id));
      case "message/stream":
        return this.stream(id, params, peer);
      default:
        return rpcError(id, ErrorCode.METHOD_NOT_FOUND, `Unknown method "${method}".`);
    }
  }

  private async invoke<P>(
    id: RpcId,
    params: unknown,
    schema: z.ZodType<P>,
    run: (params: P) => unknown | Promise<unknown>,
  ): Promise<Response> {
    const parsed = schema.safeParse(params);
    if (!parsed.success)
      return rpcError(id, ErrorCode.INVALID_PARAMS, `Invalid params: ${issueText(parsed.error)}`);
    try {
      return rpcResult(id, await run(parsed.data));
    } catch (error) {
      const failure = asError(error);
      return rpcError(id, failure.code, failure.message);
    }
  }

  private stream(id: RpcId, params: unknown, peer?: string): Response {
    const parsed = SendMessageParamsSchema.safeParse(params);
    if (!parsed.success)
      return rpcError(id, ErrorCode.INVALID_PARAMS, `Invalid params: ${issueText(parsed.error)}`, 400);
    try {
      const task = this.record(parsed.data.message, peer);
      this.options.onMessage?.(task, parsed.data.message);
      return this.streamResponse(task);
    } catch (error) {
      const failure = asError(error);
      return rpcError(id, failure.code, failure.message, httpStatus(failure.code));
    }
  }

  // One SSE stream per subscription. The recorded task is sent first so the
  // peer always sees the current state; later events arrive as the host writes
  // them and the stream ends when the task settles or is interrupted.
  private streamResponse(task: Task): Response {
    const encoder = new TextEncoder();
    let unsubscribe = () => {};
    const stream = new ReadableStream<Uint8Array>({
      start: (controller) => {
        const write = (event: StreamEvent) =>
          controller.enqueue(encoder.encode(`data: ${JSON.stringify(event)}\n\n`));
        unsubscribe = this.subscribe(task.id, (event) => {
          write(event);
          if (isStreamEnd(event)) {
            unsubscribe();
            controller.close();
          }
        });
        write(task);
        if (STREAM_END_STATES.has(task.status.state)) {
          unsubscribe();
          controller.close();
        }
      },
      cancel: () => unsubscribe(),
    });
    return new Response(stream, {
      headers: { "content-type": "text/event-stream", "cache-control": "no-cache" },
    });
  }

  private record(message: Message, peer?: string): Task {
    if (message.taskId === undefined) return this.create(message, peer);
    const task = this.tasks.get(message.taskId);
    if (task === undefined)
      throw new A2AError(ErrorCode.TASK_NOT_FOUND, `Task "${message.taskId}" not found.`);
    if (TERMINAL_STATES.has(task.status.state))
      throw new A2AError(
        ErrorCode.INVALID_PARAMS,
        `Task "${task.id}" is ${task.status.state} and cannot accept messages.`,
      );
    if (peer !== undefined && task.metadata?.peerId === undefined)
      task.metadata = { ...task.metadata, peerId: peer };
    task.history = [...(task.history ?? []), linked(message, task)];
    if (INTERRUPTED_STATES.has(task.status.state))
      task.status = { state: "TASK_STATE_SUBMITTED", timestamp: timestamp() };
    this.emit(task, task);
    return task;
  }

  private create(message: Message, peer?: string): Task {
    const task: Task = {
      id: crypto.randomUUID(),
      contextId: message.contextId ?? crypto.randomUUID(),
      status: { state: "TASK_STATE_SUBMITTED", timestamp: timestamp() },
      history: [],
      ...(peer === undefined ? {} : { metadata: { peerId: peer } }),
    };
    task.history = [linked(message, task)];
    this.tasks.set(task.id, task);
    return task;
  }

  private require(id: string): Task {
    const task = this.tasks.get(id);
    if (task === undefined)
      throw new A2AError(ErrorCode.TASK_NOT_FOUND, `Task "${id}" not found.`);
    return task;
  }

  private subscribe(taskId: string, listener: (event: StreamEvent) => void): () => void {
    const set = this.listeners.get(taskId) ?? new Set();
    set.add(listener);
    this.listeners.set(taskId, set);
    return () => {
      set.delete(listener);
      if (set.size === 0) this.listeners.delete(taskId);
    };
  }

  private emit(task: Task, event: StreamEvent): void {
    const listeners = this.listeners.get(task.id);
    if (listeners === undefined) return;
    for (const listener of [...listeners]) listener(event);
  }
}

function linked(message: Message, task: Task): Message {
  return { ...message, taskId: task.id, contextId: message.contextId ?? task.contextId };
}

function statusEvent(task: Task): StreamEvent {
  return { taskId: task.id, contextId: task.contextId ?? "", status: task.status };
}

function view(task: Task, historyLength?: number): Task {
  if (historyLength === undefined || task.history === undefined) return task;
  return { ...task, history: task.history.slice(Math.max(task.history.length - historyLength, 0)) };
}

function isStreamEnd(event: StreamEvent): boolean {
  if (!("status" in event)) return false;
  return STREAM_END_STATES.has(event.status.state);
}

function pageOffset(token: string | undefined): number {
  if (token === undefined || token === "") return 0;
  const offset = Number(token);
  if (!Number.isInteger(offset) || offset < 0)
    throw new A2AError(ErrorCode.INVALID_PARAMS, `Invalid pageToken "${token}".`);
  return offset;
}

function timestamp(): string {
  return new Date().toISOString();
}

function rpcResult(id: RpcId, result: unknown): Response {
  return Response.json({ jsonrpc: "2.0", id, result });
}

function rpcError(id: RpcId, code: number, message: string, status = 200): Response {
  return Response.json({ jsonrpc: "2.0", id, error: { code, message } }, { status });
}

function asError(error: unknown): { code: number; message: string } {
  if (error instanceof A2AError) return { code: error.code, message: error.message };
  return {
    code: ErrorCode.INTERNAL_ERROR,
    message: error instanceof Error ? error.message : "Internal error",
  };
}

// Stream setup failures must be HTTP errors: the client's stream reader only
// checks response.ok and never parses a JSON-RPC error envelope there.
function httpStatus(code: number): number {
  if (code === ErrorCode.TASK_NOT_FOUND) return 404;
  if (code === ErrorCode.INVALID_PARAMS || code === ErrorCode.INVALID_REQUEST) return 400;
  return 500;
}

function issueText(error: z.ZodError): string {
  return error.issues
    .map((issue) => `${issue.path.join(".") || "params"}: ${issue.message}`)
    .join("; ");
}

import { mkdir, unlink, writeFile } from "node:fs/promises"
import { networkInterfaces } from "node:os"
import path from "node:path"
import { AgentCardSchema } from "a2a"
import type { PeerManager } from "./peers.ts"
import type { ConversationCore } from "./conversation.ts"
import type { A2AConfig } from "./config.ts"
import type { Registry } from "./registry.ts"

export type AdminServer = {
  hostname: string
  port: number
  stop: () => Promise<void>
}

export type AdminDeps = {
  registry: Registry
  core: ConversationCore
  peers: PeerManager
  config: () => A2AConfig
  // The actually bound inbound A2A port, when the listener is up. Guards
  // against reporting a configured-but-different port (port 0 = ephemeral).
  inboundPort?: () => number | undefined
  portFile: string
  testTimeoutMs?: number
  port?: number
  hostname?: string
}

class HttpError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message)
  }
}

// The Desktop webview is a different origin from the host, so the loopback
// admin endpoint answers CORS preflight and tags every response.
const CORS = {
  "access-control-allow-origin": "*",
  "access-control-allow-methods": "GET, POST, DELETE, OPTIONS",
  "access-control-allow-headers": "content-type",
}

// A2A-014's zero-core-edit transport: a second loopback-only server, entirely
// separate from the A2A peer port, that the Desktop and TUI UIs call.
export async function startAdminServer(input: AdminDeps): Promise<AdminServer> {
  const server = Bun.serve({
    hostname: input.hostname ?? "127.0.0.1",
    port: input.port ?? 0,
    fetch: (request) => handle(request, input),
  })
  const port = server.port ?? input.port ?? 0
  await mkdir(path.dirname(input.portFile), { recursive: true })
  await writeFile(input.portFile, String(port), "utf8")
  return {
    hostname: server.hostname ?? input.hostname ?? "127.0.0.1",
    port,
    stop: async () => {
      server.stop(true)
      await unlink(input.portFile).catch(() => undefined)
    },
  }
}

async function handle(request: Request, input: AdminDeps): Promise<Response> {
  if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS })
  const parts = new URL(request.url).pathname.split("/").filter(Boolean)
  try {
    if (parts[0] !== "a2a") throw new HttpError(404, "Not found")
    if (parts[1] === "self") return await self(request, input)
    if (parts[1] === "sessions") return await sessions(request, parts, input)
    if (parts[1] === "conversations") return await conversations(request, parts, input)
    if (parts[1] === "peers") return await peers(request, parts, input)
    throw new HttpError(404, "Not found")
  } catch (error) {
    if (error instanceof HttpError) return fail(error.message, error.status)
    const message = reason(error)
    return fail(message, statusFor(message))
  }
}

async function sessions(request: Request, parts: string[], input: AdminDeps): Promise<Response> {
  if (request.method !== "GET") throw new HttpError(405, "Method not allowed")
  if (parts.length === 2) return json(input.registry.list())
  const taskId = decodeURIComponent(parts[2])
  const record = input.registry.get(taskId)
  if (record === undefined) throw new HttpError(404, `Unknown A2A task "${taskId}"`)
  return json(record)
}

// This instance's inbound socket, in the shape a peer pastes into its
// allowedPeers. The bound port wins over the configured one so an ephemeral
// bind (port 0) reports what peers should actually use. `lanUrls` lists
// addresses a peer on the same network can dial — localhost is unreachable
// from another machine.
async function self(request: Request, input: AdminDeps): Promise<Response> {
  if (request.method !== "GET") throw new HttpError(405, "Method not allowed")
  const config = input.config()
  const port = input.inboundPort?.() ?? config.listenPort
  return json({
    enabled: config.enabled,
    ...(config.name !== undefined ? { name: config.name } : {}),
    listenPort: port,
    ...(port > 0 ? { url: `http://localhost:${port}`, lanUrls: lanUrls(port) } : {}),
  })
}

function lanUrls(port: number): string[] {
  return Object.values(networkInterfaces())
    .flatMap((addresses) => addresses ?? [])
    .filter((address) => (address.family as string) === "IPv4" && !address.internal)
    .map((address) => `http://${address.address}:${port}`)
}

async function conversations(request: Request, parts: string[], input: AdminDeps): Promise<Response> {
  if (request.method !== "POST") throw new HttpError(405, "Method not allowed")
  if (parts.length === 2) {
    const payload = await body(request)
    const peer = stringField(payload, "peer")
    const message = stringField(payload, "message")
    const origin = payload.origin === undefined ? "app" : payload.origin
    if (origin !== "app" && origin !== "tui") throw new HttpError(400, 'origin must be "app" or "tui"')
    const result = await input.core.startConversation(peer, message, { origin, signal: request.signal })
    return json(result)
  }
  const taskId = decodeURIComponent(parts[2])
  const record = input.registry.get(taskId)
  if (record === undefined) throw new HttpError(404, `Unknown A2A task "${taskId}"`)
  if (parts[3] === "messages") {
    if (record.direction === "inbound") throw new HttpError(400, `Task "${taskId}" is inbound; the peer drives it`)
    const payload = await body(request)
    const message = stringField(payload, "message")
    const result = await input.core.continueConversation(taskId, message, {
      peer: record.peerId,
      origin: "app",
      signal: request.signal,
    })
    return json(result)
  }
  if (parts[3] === "cancel") {
    await input.core.cancelConversation(taskId, "canceled from control API")
    return json({ taskId, state: "TASK_STATE_CANCELED" })
  }
  throw new HttpError(404, "Not found")
}

async function peers(request: Request, parts: string[], input: AdminDeps): Promise<Response> {
  if (parts.length === 2) {
    if (request.method === "GET") return json({ peers: input.peers.list() })
    if (request.method === "POST") {
      const payload = await body(request)
      await input.peers.add(stringField(payload, "name"), stringField(payload, "url"))
      return json({ peers: input.peers.list() })
    }
    throw new HttpError(405, "Method not allowed")
  }
  const name = decodeURIComponent(parts[2])
  if (parts[3] === "test") {
    if (request.method !== "POST") throw new HttpError(405, "Method not allowed")
    const url = input.config().allowedPeers[name]
    if (url === undefined) throw new HttpError(404, `Unknown A2A peer "${name}"`)
    const card = await fetchCard(url, input.testTimeoutMs ?? 5_000)
    return json({ peer: name, name: card.name, description: card.description })
  }
  if (request.method === "DELETE") {
    await input.peers.remove(name)
    return json({ peers: input.peers.list() })
  }
  throw new HttpError(404, "Not found")
}

async function fetchCard(url: string, timeoutMs: number): Promise<{ name: string; description: string }> {
  const response = await fetch(`${url.replace(/\/+$/, "")}/.well-known/agent-card.json`, {
    signal: AbortSignal.timeout(timeoutMs),
  })
  if (!response.ok) throw new Error(`agent card request failed with HTTP ${response.status}`)
  const parsed = AgentCardSchema.safeParse(await response.json().catch(() => undefined))
  if (!parsed.success) throw new Error(`invalid agent card from "${url}"`)
  return { name: parsed.data.name, description: parsed.data.description }
}

async function body(request: Request): Promise<Record<string, unknown>> {
  const parsed = await request.json().catch(() => undefined)
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed))
    throw new HttpError(400, "Expected a JSON object body")
  return parsed as Record<string, unknown>
}

function stringField(payload: Record<string, unknown>, key: string): string {
  const value = payload[key]
  if (typeof value !== "string" || value.trim() === "") throw new HttpError(400, `${key} is required`)
  return value
}

function statusFor(message: string): number {
  if (message.startsWith("Unknown A2A peer") || message.startsWith("Unknown A2A task")) return 404
  if (/non-empty|Invalid URL|Invalid model|A2A is disabled|Expected a JSON/.test(message)) return 400
  return 502
}

function reason(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

function json(data: unknown, status = 200): Response {
  return Response.json(data, { status, headers: CORS })
}

function fail(message: string, status: number): Response {
  return Response.json({ error: message }, { status, headers: CORS })
}

import {
  A2AClient,
  A2AError,
  A2A_PEER_HEADER,
  ConversationTracker,
  type Artifact,
  type Message,
  type Part,
  type Speaker,
  type Task,
  type TaskArtifactUpdateEvent,
  type TaskState,
  type TaskStatus,
  type TaskStatusUpdateEvent,
  type Turn,
} from "a2a"
import { CAP_MESSAGE, type A2AConfig } from "./config.ts"
import type { Canceller } from "./cancel.ts"
import { noopEmitter, type A2AEventEmitter } from "./events.ts"
import type { ConversationOrigin, Registry } from "./registry.ts"

const DEFAULT_TIMEOUT_MS = 30_000
const DEFAULT_POLL_MS = 300

const TERMINAL_STATES: readonly TaskState[] = [
  "TASK_STATE_COMPLETED",
  "TASK_STATE_FAILED",
  "TASK_STATE_CANCELED",
  "TASK_STATE_REJECTED",
]
const INTERRUPTED_STATES: readonly TaskState[] = ["TASK_STATE_INPUT_REQUIRED", "TASK_STATE_AUTH_REQUIRED"]

// A conversation's config is read on every turn so a peer added through the
// local control API is usable without restarting the host. Tests pass a plain
// object; the plugin passes a getter over the live resolved config.
export type ConfigProvider = A2AConfig | (() => A2AConfig)

export function readConfig(config: ConfigProvider): A2AConfig {
  return typeof config === "function" ? config() : config
}

export type Conversation = {
  peerId: string
  client: A2AClient
  streaming: boolean
  contextId?: string
  tracker?: ConversationTracker
  // Set once the task reaches a terminal state so a follow-up cannot appear to
  // reopen a finished conversation (late replies stay ignored).
  terminal?: TaskState
  // The registry-aware emitter for this conversation, kept on the record so the
  // shared canceller emits its terminal event through the same code path that
  // keeps the session registry in sync.
  emit?: A2AEventEmitter
}

// One entry per A2A task id. The tracker is created once the task id is known,
// so every recorded turn carries the real task id.
export class ConversationStore {
  private readonly conversations = new Map<string, Conversation>()

  get(taskId: string): Conversation | undefined {
    return this.conversations.get(taskId)
  }

  save(taskId: string, conversation: Conversation): void {
    this.conversations.set(taskId, conversation)
  }
}

export type ConversationDeps = {
  config: ConfigProvider
  store: ConversationStore
  emit?: A2AEventEmitter
  cancel?: Canceller
  timeoutMs?: number
  pollMs?: number
  registry?: Registry
}

type Deps = {
  config: ConfigProvider
  store: ConversationStore
  emit: A2AEventEmitter
  cancel: Canceller
  timeoutMs: number
  pollMs: number
  registry?: Registry
}

export type ConversationOptions = {
  // Continue an existing task instead of starting a new one.
  taskId?: string
  // The remote peer; required to start, derived from the store for continue.
  peer?: string
  origin?: ConversationOrigin
  // The host session that initiated the call, when there is one.
  sessionId?: string
  signal?: AbortSignal
}

// The structured turn outcome shared by the tool renderer, the local control
// API, and the session registry.
export type ConversationResult = {
  peerId: string
  taskId?: string
  turn?: number
  firstTurn?: number
  reply?: string
  artifact?: string
  message?: string
  state: TaskState
  capped?: boolean
  terminal?: boolean
}

// The conversation machinery without the tool/model layer: `a2a_ask`, the local
// control API, and any future UI all drive the same three entry points.
export type ConversationCore = {
  startConversation: (peer: string, text: string, opts?: ConversationOptions) => Promise<ConversationResult>
  continueConversation: (taskId: string, text: string, opts?: ConversationOptions) => Promise<ConversationResult>
  cancelConversation: (taskId: string, reason?: string) => Promise<void>
}

export function createConversationCore(input: ConversationDeps): ConversationCore {
  const deps: Deps = {
    config: input.config,
    store: input.store,
    emit: input.emit ?? noopEmitter,
    cancel: input.cancel ?? (async () => undefined),
    timeoutMs: input.timeoutMs ?? DEFAULT_TIMEOUT_MS,
    pollMs: input.pollMs ?? DEFAULT_POLL_MS,
    registry: input.registry,
  }
  return {
    startConversation: (peer, text, opts) => runTurn(deps, peer, text, opts ?? {}),
    continueConversation: (taskId, text, opts) => {
      const peer = opts?.peer ?? deps.store.get(taskId)?.peerId
      if (peer === undefined || peer === "") throw new Error(`Unknown A2A task "${taskId}"`)
      return runTurn(deps, peer, text, { ...opts, taskId })
    },
    cancelConversation: async (taskId, reason) => {
      await deps.cancel(taskId, reason)
    },
  }
}

type TaskIdRef = { current?: string }

type Outcome = {
  reply?: string
  artifact?: string
  state: TaskState
}

// Start (or, when `opts.taskId` is set, resume) a conversation turn. The flow is
// the one A2A-004..013 established: resolve the task, honor the cap and terminal
// states, send one message, then stream or poll until the turn settles.
async function runTurn(deps: Deps, peer: string, text: string, opts: ConversationOptions): Promise<ConversationResult> {
  const config = readConfig(deps.config)
  if (!config.enabled) throw new Error("a2a_ask is unavailable: A2A is disabled")
  const message = text.trim()
  if (!message) throw new Error("a2a_ask requires a non-empty message")
  const baseUrl = config.allowedPeers[peer]
  if (!baseUrl) throw new Error(`Unknown A2A peer "${peer}". Allowed peers: ${allowedNames(config)}`)

  // The registry records every task and turn through the emitter, so a UI
  // reading events and a UI reading the registry can never disagree.
  const emit = attachEmitter(deps, {
    direction: "outbound",
    origin: opts.origin ?? "tool",
    peerId: peer,
    sessionId: opts.sessionId,
  })
  const scoped: Deps = { ...deps, emit }

  // A2A-012: an interrupted turn (the human pressed cancel/stop) must stop the
  // peer's task too. The listener races every network await below and cancels
  // the conversation as soon as its task id is known; the turn functions write
  // ids into `taskId` as they discover them.
  const signal = opts.signal
  const taskId = { current: opts.taskId }
  const onAbort = () => void deps.cancel(taskId.current, "canceled by user").catch(() => undefined)
  if (signal?.aborted) throw abortError()
  signal?.addEventListener("abort", onAbort, { once: true })
  try {
    const conversation = await raceAbort(signal, resolveConversation(scoped, peer, opts.taskId, baseUrl))
    conversation.emit = emit
    taskId.current = conversation.tracker?.taskId ?? taskId.current
    const tracker = conversation.tracker
    if (tracker && config.maxTurns > 0 && tracker.history().length >= config.maxTurns)
      return capResult(scoped, peer, tracker)
    if (conversation.terminal !== undefined) return terminalResult(peer, conversation)

    // The index this run's first turn will occupy. The inline UI anchors one
    // box per a2a_ask call on it, so each box shows only its own turns.
    const firstTurn = tracker?.history().length ?? 0
    const outgoing: Message = {
      messageId: crypto.randomUUID(),
      role: "ROLE_USER",
      parts: [{ text: message }],
      ...(opts.taskId ? { taskId: opts.taskId } : {}),
      ...(conversation.contextId ? { contextId: conversation.contextId } : {}),
    }
    const priorRemote = remoteCount(tracker)
    const turn = conversation.streaming
      ? streamTurn(scoped, conversation, outgoing, priorRemote, taskId, signal)
      : pollTurn(scoped, conversation, outgoing, priorRemote, taskId, signal)
    // The A2A client buffers SSE bodies, so a peer that never settles its turn
    // would hang the tool past the deadline: bound the streamed turn and cancel
    // the remote task on timeout so the peer stops working too (A2A-012
    // hardening for the A2A-004 review's buffered-SSE gap).
    const bounded = conversation.streaming
      ? withDeadline(turn, deps.timeoutMs, () => {
          void deps.cancel(taskId.current, `turn timed out after ${deps.timeoutMs}ms`).catch(() => undefined)
          return new Error(`Timed out waiting for A2A peer "${conversation.peerId}" to reply`)
        })
      : turn
    const outcome = await raceAbort(signal, bounded)
    if (TERMINAL_STATES.includes(outcome.state)) conversation.terminal = outcome.state
    return outcomeResult(conversation, outcome, firstTurn)
  } finally {
    signal?.removeEventListener("abort", onAbort)
  }
}

function attachEmitter(deps: Deps, ctx: Parameters<Registry["attach"]>[1]): A2AEventEmitter {
  if (deps.registry === undefined) return deps.emit
  return deps.registry.attach(deps.emit, ctx)
}

// The tool turn itself was aborted by the host; throwing an AbortError lets
// opencode mark the turn interrupted instead of failed.
function abortError(): Error {
  const error = new Error("a2a_ask aborted")
  error.name = "AbortError"
  return error
}

function raceAbort<T>(signal: AbortSignal | undefined, promise: Promise<T>): Promise<T> {
  if (signal === undefined) return promise
  if (signal.aborted) return Promise.reject(abortError())
  return new Promise<T>((resolve, reject) => {
    const onAbort = () => reject(abortError())
    signal.addEventListener("abort", onAbort, { once: true })
    promise.then(
      (value) => {
        signal.removeEventListener("abort", onAbort)
        resolve(value)
      },
      (error) => {
        signal.removeEventListener("abort", onAbort)
        reject(error)
      },
    )
  })
}

// Reject after `ms` even if the wrapped promise never settles. The caller's
// onTimeout supplies the error and any cleanup (for example cancelling the
// remote task) so the peer cannot keep working on a turn we gave up on.
function withDeadline<T>(promise: Promise<T>, ms: number, onTimeout: () => Error): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(onTimeout()), ms)
    promise.then(
      (value) => {
        clearTimeout(timer)
        resolve(value)
      },
      (error) => {
        clearTimeout(timer)
        reject(error)
      },
    )
  })
}

// A task id we have not seen before can still be resumed: fetch the task,
// rebuild the turn history from it, and count it toward the cap.
async function resolveConversation(
  deps: Deps,
  peer: string,
  taskId: string | undefined,
  baseUrl: string,
): Promise<Conversation> {
  if (taskId) {
    const cached = deps.store.get(taskId)
    if (cached) {
      if (cached.peerId !== peer) throw new Error(`Task "${taskId}" belongs to peer "${cached.peerId}", not "${peer}"`)
      return cached
    }
    const client = new A2AClient({ baseUrl, headers: peerHeaders(readConfig(deps.config)) })
    const task = await request(peer, () => client.getTask(taskId))
    const tracker = new ConversationTracker({ taskId: task.id })
    tracker.sync(task, speakerOf)
    const conversation: Conversation = {
      peerId: peer,
      client,
      streaming: await supportsStreaming(client),
      contextId: task.contextId,
      tracker,
    }
    deps.store.save(task.id, conversation)
    return conversation
  }
  const client = new A2AClient({ baseUrl, headers: peerHeaders(readConfig(deps.config)) })
  return { peerId: peer, client, streaming: await supportsStreaming(client) }
}

// Self-identify to the peer so its session record can name who is calling.
function peerHeaders(config: A2AConfig): Record<string, string> | undefined {
  return config.name === undefined ? undefined : { [A2A_PEER_HEADER]: config.name }
}

async function pollTurn(
  deps: Deps,
  conversation: Conversation,
  outgoing: Message,
  priorRemote: number,
  taskIdRef: TaskIdRef,
  signal?: AbortSignal,
): Promise<Outcome> {
  const response = await request(conversation.peerId, () => conversation.client.sendMessage(outgoing))

  // A synchronous peer can answer with a Message instead of a Task.
  if (isMessage(response)) {
    ensureTracker(conversation, response.taskId)
    taskIdRef.current = response.taskId ?? taskIdRef.current
    noteTurn(deps, conversation, outgoing, "local")
    noteTurn(deps, conversation, response, "remote")
    if (conversation.tracker && response.taskId) deps.store.save(response.taskId, conversation)
    return { reply: messageText(response), state: "TASK_STATE_COMPLETED" }
  }

  const fresh = conversation.tracker === undefined
  const tracker = ensureTracker(conversation, response.id)
  if (!tracker) throw new Error(`A2A peer "${conversation.peerId}" did not create a task`)
  taskIdRef.current = response.id
  if (fresh)
    deps.emit("a2a.task.dispatched", {
      taskId: response.id,
      peerId: conversation.peerId,
      state: response.status.state,
    })
  noteTurn(deps, conversation, outgoing, "local")
  syncTurns(deps, conversation, response)
  conversation.contextId ??= response.contextId
  deps.store.save(response.id, conversation)

  let task = response
  // A fresh task's first state already rode out on a2a.task.dispatched — but
  // terminal states keep their dedicated event, so only dedupe interim ones.
  let last: TaskState | undefined =
    fresh && !TERMINAL_STATES.includes(response.status.state) ? response.status.state : undefined
  const emitState = () => {
    if (task.status.state === last) return
    last = task.status.state
    emitTaskState(
      deps,
      task.id,
      conversation.peerId,
      task.status.state,
      statusText(task.status),
      task.artifacts?.at(-1),
    )
  }
  emitState()
  let outcome = taskOutcome(task, tracker, priorRemote)
  const deadline = Date.now() + deps.timeoutMs
  while (!outcome.reply && !outcome.artifact && !settled(outcome.state) && Date.now() < deadline) {
    if (signal?.aborted) throw abortError()
    await Bun.sleep(deps.pollMs)
    task = await request(conversation.peerId, () => conversation.client.getTask(task.id))
    syncTurns(deps, conversation, task)
    emitState()
    conversation.contextId ??= task.contextId
    outcome = taskOutcome(task, tracker, priorRemote)
  }

  if (outcome.state === "TASK_STATE_FAILED" || outcome.state === "TASK_STATE_CANCELED") {
    conversation.terminal = outcome.state
    throw new Error(`A2A peer "${conversation.peerId}" ended task ${task.id} with ${outcome.state}`)
  }
  if (!outcome.reply && !outcome.artifact && !settled(outcome.state)) {
    // The turn outlived the deadline: stop the peer from working on a task we
    // are no longer waiting for, then surface the timeout as before. The
    // cancel is fire-and-forget so an unresponsive peer cannot hang the tool.
    void deps.cancel(taskIdRef.current, "turn timed out").catch(() => undefined)
    throw new Error(`Timed out waiting for A2A peer "${conversation.peerId}" to reply (task ${task.id})`)
  }
  return outcome
}

async function streamTurn(
  deps: Deps,
  conversation: Conversation,
  outgoing: Message,
  priorRemote: number,
  taskIdRef: TaskIdRef,
  signal?: AbortSignal,
): Promise<Outcome> {
  const peer = conversation.peerId
  const deadline = Date.now() + deps.timeoutMs
  const fresh = conversation.tracker === undefined
  let task: Task | undefined
  let taskId: string | undefined
  let contextId: string | undefined
  let reply: string | undefined
  let replyMessage: Message | undefined
  const streamed: Message[] = []
  let artifact: string | undefined
  let lastArtifact: Artifact | undefined
  let state: TaskState | undefined
  let last: TaskState | undefined
  let dispatched = false
  const seeTaskId = (id: string | undefined) => {
    if (id === undefined) return
    taskId = id
    taskIdRef.current = id
  }
  const emitState = (next: TaskState, id: string | undefined, content?: string, seen?: Artifact) => {
    if (!id || next === last) return
    last = next
    emitTaskState(deps, id, peer, next, content, seen)
  }
  const markDispatched = (id: string | undefined, next: TaskState | undefined) => {
    if (!fresh || !id || dispatched) return
    dispatched = true
    const initial = next ?? "TASK_STATE_SUBMITTED"
    // The dispatch event already carries this state; dedupe it from updated —
    // unless it is terminal, which still needs its dedicated event type.
    if (!TERMINAL_STATES.includes(initial)) last = initial
    deps.emit("a2a.task.dispatched", { taskId: id, peerId: peer, state: initial })
  }

  try {
    for await (const event of conversation.client.streamMessage(outgoing)) {
      if (signal?.aborted) throw abortError()
      if (Date.now() > deadline) throw new Error(`Timed out waiting for A2A peer "${peer}" to reply`)
      if (isStatusUpdate(event)) {
        taskId ??= event.taskId
        seeTaskId(taskId)
        contextId ??= event.contextId
        state = event.status.state
        markDispatched(taskId, state)
        emitState(state, taskId, statusText(event.status), lastArtifact)
        if (event.status.message) {
          reply = messageText(event.status.message)
          replyMessage = event.status.message
        }
        continue
      }
      if (isArtifactUpdate(event)) {
        taskId ??= event.taskId
        seeTaskId(taskId)
        contextId ??= event.contextId
        artifact = partsText(event.artifact.parts)
        lastArtifact = event.artifact
        continue
      }
      if (isTask(event)) {
        task = event
        taskId ??= event.id
        seeTaskId(taskId)
        contextId ??= event.contextId
        state = event.status.state
        markDispatched(taskId, state)
        lastArtifact = event.artifacts?.at(-1) ?? lastArtifact
        emitState(state, taskId, statusText(event.status), lastArtifact)
        continue
      }
      reply = messageText(event)
      replyMessage = event
      streamed.push(event)
    }
  } catch (error) {
    if (error instanceof A2AError) throw new Error(`A2A peer "${peer}" error ${error.code}: ${error.message}`)
    throw error instanceof Error ? error : new Error(String(error))
  }

  if (fresh && taskId && !dispatched) {
    seeTaskId(taskId)
    deps.emit("a2a.task.dispatched", { taskId, peerId: peer, state: state ?? "TASK_STATE_SUBMITTED" })
  }
  const tracker = ensureTracker(conversation, taskId)
  noteTurn(deps, conversation, outgoing, "local")
  if (task) syncTurns(deps, conversation, task)
  // The task snapshot is written before the host appends its reply, so the
  // reply only shows up as a stream event: note it or the turn cap would
  // under-count every streamed reply and let extra asks through.
  for (const message of streamed) noteTurn(deps, conversation, message, "remote")
  if (!task && replyMessage) noteTurn(deps, conversation, replyMessage, "remote")
  conversation.contextId ??= contextId
  if (tracker && taskId) deps.store.save(taskId, conversation)

  const outcome: Outcome = {
    reply: reply ?? (tracker && remoteCount(tracker) > priorRemote ? lastRemoteText(tracker) : undefined),
    artifact: artifact ?? (task ? artifactText(task) : undefined),
    state: state ?? task?.status.state ?? (reply ? "TASK_STATE_COMPLETED" : "TASK_STATE_WORKING"),
  }

  // Mirror pollTurn: a failed, canceled, or truncated stream must surface as an
  // error instead of a successful turn with "Reply: (none)".
  if (outcome.state === "TASK_STATE_FAILED" || outcome.state === "TASK_STATE_CANCELED") {
    conversation.terminal = outcome.state
    throw new Error(`A2A peer "${peer}" ended task ${taskId ?? task?.id ?? "unknown"} with ${outcome.state}`)
  }
  if (!outcome.reply && !outcome.artifact && !settled(outcome.state))
    throw new Error(`A2A peer "${peer}" ended the stream without a reply (task ${taskId ?? "unknown"})`)
  return outcome
}

async function request<T>(peer: string, call: () => Promise<T>): Promise<T> {
  try {
    return await call()
  } catch (error) {
    if (error instanceof A2AError) throw new Error(`A2A peer "${peer}" error ${error.code}: ${error.message}`)
    throw new Error(`A2A peer "${peer}" request failed: ${error instanceof Error ? error.message : String(error)}`)
  }
}

async function supportsStreaming(client: A2AClient): Promise<boolean> {
  try {
    const card = await client.fetchAgentCard()
    return card.capabilities.streaming === true
  } catch {
    // A peer without a readable card can still be driven with send + poll.
    return false
  }
}

function outcomeResult(conversation: Conversation, outcome: Outcome, firstTurn: number): ConversationResult {
  const tracker = conversation.tracker
  return {
    peerId: conversation.peerId,
    ...(tracker ? { taskId: tracker.taskId, turn: tracker.history().length } : {}),
    firstTurn,
    ...(outcome.reply === undefined ? {} : { reply: outcome.reply }),
    ...(outcome.artifact === undefined ? {} : { artifact: outcome.artifact }),
    state: outcome.state,
  }
}

function terminalResult(peer: string, conversation: Conversation): ConversationResult {
  const state = conversation.terminal ?? "TASK_STATE_COMPLETED"
  const tracker = conversation.tracker
  return {
    peerId: peer,
    ...(tracker ? { taskId: tracker.taskId } : {}),
    state,
    terminal: true,
  }
}

function capResult(deps: Deps, peer: string, tracker: ConversationTracker): ConversationResult {
  deps.emit("a2a.task.completed", {
    taskId: tracker.taskId,
    peerId: peer,
    state: "TASK_STATE_COMPLETED",
    content: CAP_MESSAGE,
  })
  return {
    peerId: peer,
    taskId: tracker.taskId,
    turn: tracker.history().length,
    state: "TASK_STATE_COMPLETED",
    message: CAP_MESSAGE,
    capped: true,
  }
}

function allowedNames(config: A2AConfig): string {
  const names = Object.keys(config.allowedPeers)
  return names.length ? names.join(", ") : "(none configured)"
}

function ensureTracker(conversation: Conversation, taskId: string | undefined): ConversationTracker | undefined {
  if (conversation.tracker) return conversation.tracker
  if (!taskId) return undefined
  conversation.tracker = new ConversationTracker({ taskId })
  return conversation.tracker
}

function speakerOf(message: Message): Speaker {
  return message.role === "ROLE_USER" ? "local" : "remote"
}

// A2A-008 fan-out: every recorded turn leaves as one a2a.conversation.turn
// event so the UI can render the thread without polling tasks/get.
function noteTurn(deps: Deps, conversation: Conversation, message: Message, speaker: Speaker): void {
  const tracker = conversation.tracker
  if (!tracker) {
    // A peer answering with a bare Message may carry no task at all; still
    // emit the turn so the UI thread shows it.
    deps.emit("a2a.conversation.turn", {
      speaker,
      turn: speaker === "local" ? 0 : 1,
      taskId: message.taskId,
      peerId: speaker === "local" ? readConfig(deps.config).name : conversation.peerId,
      content: messageText(message),
    })
    return
  }
  const note = tracker.note(message, speaker)
  if (note.kind === "added") emitTurn(deps, conversation, note.turn)
}

function syncTurns(deps: Deps, conversation: Conversation, task: Task): void {
  const tracker = conversation.tracker
  if (!tracker) return
  for (const note of tracker.sync(task, speakerOf)) {
    if (note.kind === "added") emitTurn(deps, conversation, note.turn)
  }
}

function emitTurn(deps: Deps, conversation: Conversation, turn: Turn): void {
  deps.emit("a2a.conversation.turn", {
    speaker: turn.speaker,
    turn: turn.index,
    taskId: turn.taskId,
    peerId: turn.speaker === "local" ? readConfig(deps.config).name : conversation.peerId,
    content: turn.text,
  })
}

// Terminal states map to their own event types; everything else is a generic
// a2a.task.updated, which also carries TASK_STATE_CANCELED.
function emitTaskState(
  deps: Deps,
  taskId: string,
  peerId: string,
  state: TaskState,
  content?: string,
  artifact?: Artifact,
): void {
  const properties = {
    taskId,
    peerId,
    state,
    ...(content === undefined ? {} : { content }),
    ...(artifact === undefined ? {} : { artifact }),
  }
  if (state === "TASK_STATE_COMPLETED") deps.emit("a2a.task.completed", properties)
  else if (state === "TASK_STATE_FAILED") deps.emit("a2a.task.failed", properties)
  else deps.emit("a2a.task.updated", properties)
}

function statusText(status: TaskStatus): string | undefined {
  return status.message ? messageText(status.message) : undefined
}

function remoteCount(tracker: ConversationTracker | undefined): number {
  return tracker ? tracker.history().filter((turn) => turn.speaker === "remote").length : 0
}

function lastRemoteText(tracker: ConversationTracker): string | undefined {
  const turns = tracker.history()
  for (let index = turns.length - 1; index >= 0; index--) {
    const turn = turns[index]
    if (turn.speaker === "remote") return turn.text
  }
  return undefined
}

function taskOutcome(task: Task, tracker: ConversationTracker, priorRemote: number): Outcome {
  return {
    reply: remoteCount(tracker) > priorRemote ? lastRemoteText(tracker) : undefined,
    artifact: artifactText(task),
    state: task.status.state,
  }
}

function messageText(message: Message): string {
  return partsText(message.parts)
}

function partsText(parts: Part[]): string {
  return parts.map((part) => part.text).join("\n")
}

function artifactText(task: Task): string | undefined {
  const artifact = task.artifacts?.at(-1)
  if (!artifact) return undefined
  return partsText(artifact.parts)
}

function settled(state: TaskState): boolean {
  return TERMINAL_STATES.includes(state) || INTERRUPTED_STATES.includes(state)
}

function isMessage(value: unknown): value is Message {
  return (
    isRecord(value) &&
    typeof value.messageId === "string" &&
    typeof value.role === "string" &&
    Array.isArray(value.parts)
  )
}

function isTask(value: unknown): value is Task {
  return isRecord(value) && typeof value.id === "string" && isRecord(value.status)
}

function isStatusUpdate(value: unknown): value is TaskStatusUpdateEvent {
  return isRecord(value) && typeof value.taskId === "string" && isRecord(value.status)
}

function isArtifactUpdate(value: unknown): value is TaskArtifactUpdateEvent {
  return isRecord(value) && typeof value.taskId === "string" && isRecord(value.artifact)
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

import {
  A2AServer,
  ConversationTracker,
  type AgentCard,
  type Message,
  type Task,
  type TaskState,
  type TaskStatus,
} from "a2a"
import { CAP_MESSAGE, type A2AConfig } from "./config.ts"
import { noopEmitter, type A2AEventEmitter } from "./events.ts"
import type { Registry } from "./registry.ts"
import { isSessionAborted, type SessionRunner } from "./session.ts"

// One entry per A2A task id. sessionID lands here after the first successful
// run, the tracker owns dedupe plus the turn count behind the cap, and the
// queue serializes turns so messages arriving mid-run wait their turn.
type InboundState = {
  sessionID?: string
  tracker: ConversationTracker
  queue: Promise<void>
  emit: A2AEventEmitter
}

// Serves inbound A2A tasks through local opencode sessions: the A2A server
// records work and notifies, this bridge runs it (fire-and-forget, because
// onMessage is synchronous) and writes replies and status transitions back via
// appendMessage/setStatus so open streams and tasks/get observe them.
export function startInboundServer(input: {
  config: A2AConfig
  runner: SessionRunner
  emit?: A2AEventEmitter
  registry?: Registry
}): {
  stop: () => void
  port: number
  cancel: (taskId: string) => Promise<boolean>
} {
  const emit = input.emit ?? noopEmitter
  const states = new Map<string, InboundState>()
  let server: A2AServer

  // A2A-012: the shared cancel path used when a local run is interrupted.
  // Unknown, already settled, or failed cleanup all read as "not cancelled";
  // callers treat cancellation as best-effort.
  const cancel = async (taskId: string): Promise<boolean> => {
    try {
      if (settled(server.getTask(taskId).status.state)) return false
      await server.cancelTask(taskId)
      return true
    } catch {
      return false
    }
  }

  // A2A-012: a turn must never leave the task WORKING forever. On timeout the
  // session is aborted and the run rejects, which surfaces as TASK_STATE_FAILED
  // (timeouts are real errors per the turn-cap rules).
  const runWithTimeout = (taskId: string, text: string, peer?: string) => {
    const timeoutMs = input.config.turnTimeoutMs
    return new Promise<{ sessionID: string; text: string }>((resolve, reject) => {
      const timer = setTimeout(() => {
        void input.runner.abort(taskId).catch(() => undefined)
        reject(new Error(`turn timed out after ${timeoutMs}ms`))
      }, timeoutMs)
      input.runner.run(taskId, text, peer).then(
        (run) => {
          clearTimeout(timer)
          resolve(run)
        },
        (error) => {
          clearTimeout(timer)
          reject(error)
        },
      )
    })
  }

  // Every task transition the bridge writes also leaves as an a2a.task.* event
  // so the UI thread view tracks the wire state without polling. The task's own
  // emitter (registry-aware when a registry is present) is used so the session
  // registry stays in lockstep with the bus.
  const notify = (emitter: A2AEventEmitter, task: Task, status: TaskStatus) => {
    server.setStatus(task.id, status)
    const properties = {
      taskId: task.id,
      peerId: peerOf(task),
      state: status.state,
      ...(status.message ? { content: messageText(status.message) } : {}),
      ...(status.state === "TASK_STATE_COMPLETED" && task.artifacts?.length ? { artifact: task.artifacts.at(-1) } : {}),
    }
    if (status.state === "TASK_STATE_COMPLETED") emitter("a2a.task.completed", properties)
    else if (status.state === "TASK_STATE_FAILED") emitter("a2a.task.failed", properties)
    else emitter("a2a.task.updated", properties)
  }

  const respond = async (state: InboundState, task: Task, message: Message) => {
    if (settled(task.status.state)) return
    const text = messageText(message).trim()
    if (!text) {
      notify(state.emit, task, failed("message contained no text"))
      return
    }
    notify(state.emit, task, { state: "TASK_STATE_WORKING" })
    let run: { sessionID: string; text: string }
    try {
      run = await runWithTimeout(task.id, text, peerOf(task))
    } catch (error) {
      if (settled(task.status.state)) return
      // A2A-012: an interrupted session is a cancel, not a failure. Settle the
      // local task CANCELED (the peer observes it on its stream/poll) instead
      // of reporting the abort as TASK_STATE_FAILED.
      if (isSessionAborted(error)) {
        await cancel(task.id)
        return
      }
      notify(state.emit, task, failed(reason(error)))
      return
    }
    // A cancel may have settled the task while the session ran; never write a
    // late reply onto a settled task.
    if (settled(task.status.state)) return
    state.sessionID = run.sessionID
    input.registry?.setSession(task.id, run.sessionID)
    const reply: Message = {
      messageId: crypto.randomUUID(),
      role: "ROLE_AGENT",
      parts: [{ text: run.text }],
    }
    server.appendMessage(task.id, reply)
    const note = state.tracker.note(reply, "local")
    if (note.kind === "added")
      state.emit("a2a.conversation.turn", {
        speaker: "local",
        turn: note.turn.index,
        taskId: task.id,
        peerId: input.config.name,
        content: note.turn.text,
      })
    // Multi-turn needs INPUT_REQUIRED between turns: a COMPLETED task rejects
    // follow-ups with -32602. Only the cap closes the conversation. The final
    // reply doubles as the verdict artifact so peers (and the UI) can read the
    // outcome via tasks/get without replaying history.
    if (input.config.maxTurns > 0 && state.tracker.history().length >= input.config.maxTurns) {
      server.appendArtifact(task.id, {
        artifactId: `${task.id}-verdict`,
        name: "verdict",
        parts: [{ text: run.text }],
      })
      notify(state.emit, task, {
        state: "TASK_STATE_COMPLETED",
        message: { messageId: crypto.randomUUID(), role: "ROLE_AGENT", parts: [{ text: CAP_MESSAGE }] },
      })
    } else notify(state.emit, task, { state: "TASK_STATE_INPUT_REQUIRED" })
  }

  const onMessage = (task: Task, message: Message) => {
    const known = states.has(task.id)
    const state: InboundState = states.get(task.id) ?? {
      tracker: new ConversationTracker({ taskId: task.id }),
      queue: Promise.resolve(),
      emit: input.registry?.attach(emit, { direction: "inbound", origin: "peer", peerId: peerOf(task) }) ?? emit,
    }
    states.set(task.id, state)
    if (!known) state.emit("a2a.task.dispatched", { taskId: task.id, peerId: peerOf(task), state: task.status.state })
    const note = state.tracker.note(message, "remote")
    if (note.kind === "added")
      state.emit("a2a.conversation.turn", {
        speaker: "remote",
        turn: note.turn.index,
        taskId: task.id,
        peerId: peerOf(task),
        content: note.turn.text,
      })
    if (note.kind === "duplicate") {
      // The server recorded the duplicate and reset an INPUT_REQUIRED task to
      // SUBMITTED; put it back so the retried delivery sees the same settled
      // turn without re-running the session or appending the reply twice.
      if (task.status.state === "TASK_STATE_SUBMITTED")
        notify(state.emit, task, { state: "TASK_STATE_INPUT_REQUIRED" })
      return
    }
    state.queue = state.queue.then(() => respond(state, task, message))
  }

  server = new A2AServer({
    // Deferred so the card reports the port Bun.serve actually bound (0 asks
    // for an ephemeral port, which peers only learn from the card).
    card: () => cardFor(port, input.config.name),
    onMessage,
    onCancel: (task) => {
      // The server already transitioned the task; echo it so CANCELED reaches
      // the UI stream like every other state change. Use the task's own emitter
      // so the registry records the cancel too.
      const emitter = states.get(task.id)?.emit ?? emit
      emitter("a2a.task.updated", { taskId: task.id, peerId: peerOf(task), state: "TASK_STATE_CANCELED" })
      return input.runner.abort(task.id)
    },
  })
  // The socket address is the identity fallback when the peer does not send
  // the x-a2a-peer header; the server prefers the header when present.
  const listener = Bun.serve({
    port: input.config.listenPort,
    fetch: (request, self) => server.fetch(request, self.requestIP(request)?.address),
  })
  const port = listener.port ?? input.config.listenPort
  return { stop: () => listener.stop(true), port, cancel }
}

function cardFor(port: number, name?: string): AgentCard {
  return {
    // A2A-013: the card name is the configured self-identity (the same value
    // peers receive in the x-a2a-peer header), falling back to "opencode".
    name: name ?? "opencode",
    description: "Hold a multi-turn conversation with a local opencode agent",
    version: "1.0.0",
    supportedInterfaces: [{ url: `http://localhost:${port}/`, protocolBinding: "JSONRPC", protocolVersion: "1.0" }],
    capabilities: { streaming: true },
    defaultInputModes: ["text/plain"],
    defaultOutputModes: ["text/plain"],
    skills: [
      {
        id: "chat",
        name: "Chat",
        description: "Answer questions and continue a task-scoped conversation",
        tags: ["chat"],
      },
    ],
  }
}

// Terminal states only. A settled task must never be resurrected by a queued
// message, a late reply, or a failing run.
function settled(state: TaskState): boolean {
  return (
    state === "TASK_STATE_COMPLETED" ||
    state === "TASK_STATE_FAILED" ||
    state === "TASK_STATE_CANCELED" ||
    state === "TASK_STATE_REJECTED"
  )
}

function failed(text: string): TaskStatus {
  return {
    state: "TASK_STATE_FAILED",
    message: { messageId: crypto.randomUUID(), role: "ROLE_AGENT", parts: [{ text }] },
  }
}

function messageText(message: Message): string {
  return message.parts.map((part) => part.text).join("\n")
}

function peerOf(task: Task): string | undefined {
  const peer = task.metadata?.peerId
  return typeof peer === "string" ? peer : undefined
}

function reason(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

import { readFile, writeFile } from "node:fs/promises"
import { homedir } from "node:os"
import path from "node:path"
import { applyEdits, modify, parse as parseJsonc } from "jsonc-parser"
import { requireUrl, type A2AConfig } from "./config.ts"

export type AllowedPeer = { name: string; url: string }

export type PeerEdit = {
  file: string
  // The plugin entry's options object (nested or flat) with the edit applied,
  // ready to feed back through resolveConfig for a live re-apply.
  options: Record<string, unknown>
}

type Shape = "nested" | "flat"

type Registration = {
  spec: string
  index: number
  shape: Shape
  options?: Record<string, unknown>
  // Path to the allowedPeers object, for jsonc modify.
  path: Array<string | number>
  // A bare spec string has no options object yet; writing upgrades it to a
  // nested [spec, { a2a: { ... } }] tuple.
  upgrade: boolean
}

// Mirrors packages/opencode/src/plugin/install.ts: modify the whole document
// with jsonc-parser so comments and unrelated keys stay byte-identical.
function patch(text: string, at: Array<string | number>, value: unknown) {
  return applyEdits(
    text,
    modify(text, at, value, {
      formattingOptions: { tabSize: 2, insertSpaces: true },
    }),
  )
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function specMatches(spec: string): boolean {
  return spec.includes("plugin-a2a")
}

// Ours is the plugin entry whose spec names plugin-a2a, or whose options own an
// `a2a` section. The shape decides where `allowedPeers` lives.
export function findRegistration(data: unknown): Registration | undefined {
  if (!isRecord(data) || !Array.isArray(data.plugin)) return
  const list = data.plugin
  for (let index = 0; index < list.length; index++) {
    const item = list[index]
    if (typeof item === "string") {
      if (!specMatches(item)) continue
      return {
        spec: item,
        index,
        shape: "nested",
        path: ["plugin", index, 1, "a2a", "allowedPeers"],
        upgrade: true,
      }
    }
    if (!Array.isArray(item)) continue
    const spec = typeof item[0] === "string" ? item[0] : undefined
    const options = isRecord(item[1]) ? item[1] : undefined
    const nested = isRecord(options?.a2a) ? options.a2a : undefined
    if (spec !== undefined && specMatches(spec)) {
      // No options object yet, or a nested one: default to nested so an upgrade
      // writes a consistent [spec, { a2a: { ... } }] tuple.
      const shape: Shape = options === undefined || nested !== undefined ? "nested" : "flat"
      return {
        spec,
        index,
        shape,
        options,
        path:
          shape === "nested"
            ? ["plugin", index, 1, "a2a", "allowedPeers"]
            : ["plugin", index, 1, "allowedPeers"],
        upgrade: options === undefined,
      }
    }
    if (nested !== undefined) {
      return {
        spec: spec ?? "plugin-a2a",
        index,
        shape: "nested",
        options,
        path: ["plugin", index, 1, "a2a", "allowedPeers"],
        upgrade: false,
      }
    }
  }
}

function atPath(data: unknown, path: Array<string | number>): unknown {
  let current: unknown = data
  for (const key of path) {
    if (typeof key === "number") {
      if (!Array.isArray(current)) return undefined
      current = current[key]
      continue
    }
    if (!isRecord(current)) return undefined
    current = current[key]
  }
  return current
}

function readPeers(data: unknown, reg: Registration): Record<string, string> {
  const value = atPath(data, reg.path)
  if (!isRecord(value)) return {}
  return Object.fromEntries(
    Object.entries(value).filter((entry): entry is [string, string] => typeof entry[1] === "string"),
  )
}

// The plugin entry options (not just the a2a section) with `allowedPeers`
// replaced, preserving the entry's shape so a live re-resolve reads it back.
function optionsWithPeers(reg: Registration, peers: Record<string, string>): Record<string, unknown> {
  if (reg.shape === "nested") {
    const a2a = isRecord(reg.options?.a2a) ? reg.options.a2a : {}
    return { ...(reg.options ?? {}), a2a: { ...a2a, allowedPeers: peers } }
  }
  return { ...(reg.options ?? {}), allowedPeers: peers }
}

function writePeers(text: string, reg: Registration, peers: Record<string, string>): string {
  const upgraded = reg.upgrade ? patch(text, ["plugin", reg.index], [reg.spec, { a2a: {} }]) : text
  return patch(upgraded, reg.path, peers)
}

export type PeerStore = {
  readPeers: () => Promise<AllowedPeer[]>
  addPeer: (name: string, url: string) => Promise<PeerEdit>
  removePeer: (name: string) => Promise<PeerEdit>
}

// The single source of truth stays `a2a.allowedPeers` in the config file. This
// store locates the plugin's own registration (project file first, then the
// global config) and edits only the allowedPeers subtree, in place.
export function createPeerStore(input: {
  directory?: string
  globalConfigDir?: string
  // Test seam: an explicit candidate list replaces the default search.
  files?: string[]
}): PeerStore {
  const candidates = (): string[] => {
    if (input.files !== undefined) return input.files
    const globalDir = input.globalConfigDir ?? path.join(homedir(), ".config", "opencode")
    return [
      path.join(input.directory ?? ".", "opencode.json"),
      path.join(globalDir, "opencode.json"),
      path.join(globalDir, "opencode.jsonc"),
    ]
  }

  const locate = async (): Promise<{ file: string; text: string; data: unknown; reg: Registration } | undefined> => {
    for (const file of candidates()) {
      const text = await readFile(file, "utf8").catch(() => undefined)
      if (text === undefined || text.trim() === "") continue
      const errors: unknown[] = []
      const data = parseJsonc(text, errors as never, { allowTrailingComma: true })
      if (errors.length > 0) continue
      const reg = findRegistration(data)
      if (reg !== undefined) return { file, text, data, reg }
    }
    return undefined
  }

  const edit = async (mutate: (peers: Record<string, string>) => Record<string, string>): Promise<PeerEdit> => {
    const located = await locate()
    if (located === undefined) {
      throw new Error(
        `No editable A2A registration found (checked ${candidates().join(", ")}). ` +
          `Add the peer by hand to the "allowedPeers" of the plugin-a2a entry in opencode.json.`,
      )
    }
    const peers = mutate(readPeers(located.data, located.reg))
    const text = writePeers(located.text, located.reg, peers)
    const write = await writeFile(located.file, text, "utf8").catch((error: unknown) => error)
    if (write instanceof Error) {
      throw new Error(
        `Could not write ${located.file}: ${write.message}. Edit the "allowedPeers" of the plugin-a2a entry by hand.`,
      )
    }
    return { file: located.file, options: optionsWithPeers(located.reg, peers) }
  }

  return {
    readPeers: async () => {
      const located = await locate()
      if (located === undefined) return []
      return Object.entries(readPeers(located.data, located.reg)).map(([name, url]) => ({ name, url }))
    },
    addPeer: async (name, url) => {
      const trimmed = name.trim()
      if (!trimmed) throw new Error("A2A peer name must be a non-empty string")
      requireUrl(trimmed, url)
      return edit((peers) => ({ ...peers, [trimmed]: url }))
    },
    removePeer: async (name) =>
      edit((peers) => {
        if (!(name in peers)) throw new Error(`Unknown A2A peer "${name}"`)
        const { [name]: _removed, ...rest } = peers
        return rest
      }),
  }
}

export type PeerManager = {
  list: () => AllowedPeer[]
  add: (name: string, url: string) => Promise<void>
  remove: (name: string) => Promise<void>
}

// Wraps the store with the live config: after a JSONC write the edited file's
// options are re-resolved and applied, so the running tool sees the new peers
// without a restart.
export function createPeerManager(input: {
  directory?: string
  globalConfigDir?: string
  files?: string[]
  config: () => A2AConfig
  resolve: (options: Record<string, unknown>) => A2AConfig
  apply: (config: A2AConfig) => void
}): PeerManager {
  const store = createPeerStore({
    directory: input.directory,
    globalConfigDir: input.globalConfigDir,
    files: input.files,
  })
  const apply = async (options: Record<string, unknown>) => {
    input.apply(input.resolve(options))
  }
  return {
    list: () =>
      Object.entries(input.config().allowedPeers).map(([name, url]) => ({ name, url })),
    add: async (name, url) => {
      const edit = await store.addPeer(name, url)
      await apply(edit.options)
    },
    remove: async (name) => {
      if (!(name in input.config().allowedPeers)) throw new Error(`Unknown A2A peer "${name}"`)
      const edit = await store.removePeer(name)
      await apply(edit.options)
    },
  }
}

import { mkdir, readFile, rename, writeFile } from "node:fs/promises"
import path from "node:path"
import type { TaskState } from "a2a"
import type { A2AEventEmitter } from "./events.ts"

export type ConversationDirection = "outbound" | "inbound"
export type ConversationOrigin = "tool" | "tui" | "app" | "peer"

// The context that makes a task record meaningful but that the a2a.* events do
// not carry: who started it, which side of the bridge it is on, and (when there
// is one) the host session behind it.
export type RegistryContext = {
  direction: ConversationDirection
  origin: ConversationOrigin
  peerId?: string
  sessionId?: string
}

export type TaskTurn = {
  speaker: "local" | "remote"
  turn: number
  peerId?: string
  taskId?: string
  content: string
}

export type TaskRecord = {
  taskId: string
  direction: ConversationDirection
  origin: ConversationOrigin
  peerId?: string
  state: TaskState
  turns: number
  sessionId?: string
  message?: string
  // Full conversation capture so UIs can render a task after the fact, not
  // only from live events: the turn log and state chain (both capped), plus
  // the latest verdict artifact.
  history?: TaskTurn[]
  states?: TaskState[]
  artifact?: unknown
  createdAt: number
  updatedAt: number
}

const TERMINAL_STATES = new Set<TaskState>([
  "TASK_STATE_COMPLETED",
  "TASK_STATE_FAILED",
  "TASK_STATE_CANCELED",
  "TASK_STATE_REJECTED",
])

// A process that died leaves tasks marked WORKING/SUBMITTED; a restarted host
// has no way to continue them, so they settle as failed rather than looking
// live forever.
const RESTART_MESSAGE = "host restarted"
const DEFAULT_LIMIT = 50
const HISTORY_LIMIT = 40
const STATES_LIMIT = 20

export type Registry = {
  // Wrap the base emitter so every a2a.task.* / a2a.conversation.turn goes to
  // the bus and the registry from the same call — the two cannot drift.
  attach: (base: A2AEventEmitter, ctx: RegistryContext) => A2AEventEmitter
  setSession: (taskId: string, sessionId: string) => void
  list: () => TaskRecord[]
  get: (taskId: string) => TaskRecord | undefined
  // Read the persisted state and settle any task a dead process left running.
  load: () => Promise<void>
  // Resolves once every scheduled write has landed; used by tests.
  flush: () => Promise<void>
}

export function createConversationRegistry(input: {
  file: string
  limit?: number
  now?: () => number
}): Registry {
  const limit = input.limit ?? DEFAULT_LIMIT
  const now = input.now ?? (() => Date.now())
  const records = new Map<string, TaskRecord>()
  let pending: Promise<void> = Promise.resolve()

  const createRecord = (taskId: string, ctx: RegistryContext, timestamp: number): TaskRecord => ({
    taskId,
    direction: ctx.direction,
    origin: ctx.origin,
    ...(ctx.peerId === undefined ? {} : { peerId: ctx.peerId }),
    state: "TASK_STATE_SUBMITTED",
    turns: 0,
    ...(ctx.sessionId === undefined ? {} : { sessionId: ctx.sessionId }),
    createdAt: timestamp,
    updatedAt: timestamp,
  })

  const prune = () => {
    if (records.size <= limit) return
    const newestFirst = [...records.values()].sort((a, b) => b.updatedAt - a.updatedAt)
    for (const record of newestFirst.slice(limit)) records.delete(record.taskId)
  }

  const persist = async () => {
    prune()
    const payload = JSON.stringify({ version: 1, tasks: [...records.values()] }, null, 2)
    await mkdir(path.dirname(input.file), { recursive: true })
    // Atomic: write a sibling temp file, then swap it into place.
    const tmp = `${input.file}.tmp`
    await writeFile(tmp, payload, "utf8")
    await rename(tmp, input.file)
  }

  const schedule = () => {
    pending = pending.then(persist).catch(() => undefined)
  }

  const observe = (type: string, properties: Record<string, unknown>, ctx: RegistryContext) => {
    const taskId = typeof properties.taskId === "string" ? properties.taskId : undefined
    if (taskId === undefined) return
    const existing = records.get(taskId)
    const timestamp = now()
    if (type === "a2a.conversation.turn") {
      const turn = typeof properties.turn === "number" ? properties.turn : 0
      const record = existing ?? createRecord(taskId, ctx, timestamp)
      record.turns = Math.max(record.turns, turn + 1)
      const speaker = properties.speaker === "local" || properties.speaker === "remote" ? properties.speaker : undefined
      if (speaker !== undefined) {
        const entry: TaskTurn = {
          speaker,
          turn,
          taskId,
          ...(typeof properties.peerId === "string" ? { peerId: properties.peerId } : {}),
          content: typeof properties.content === "string" ? properties.content : "",
        }
        record.history = [...(record.history ?? []), entry].slice(-HISTORY_LIMIT)
      }
      record.updatedAt = timestamp
      records.set(taskId, record)
      schedule()
      return
    }
    const record = existing ?? createRecord(taskId, ctx, timestamp)
    if (typeof properties.state === "string") {
      record.state = properties.state as TaskState
      if (record.states?.at(-1) !== record.state)
        record.states = [...(record.states ?? []), record.state].slice(-STATES_LIMIT)
    }
    if (typeof properties.content === "string") record.message = properties.content
    if (properties.artifact !== undefined) record.artifact = properties.artifact
    if (ctx.sessionId !== undefined) record.sessionId = ctx.sessionId
    record.updatedAt = timestamp
    records.set(taskId, record)
    schedule()
  }

  const restore = async (text: string) => {
    let parsed: unknown
    try {
      parsed = JSON.parse(text)
    } catch {
      return
    }
    if (!isRecord(parsed) || !Array.isArray(parsed.tasks)) return
    for (const entry of parsed.tasks) {
      if (!isRecord(entry) || typeof entry.taskId !== "string") continue
      records.set(entry.taskId, entry as unknown as TaskRecord)
    }
    let changed = false
    for (const record of records.values()) {
      if (TERMINAL_STATES.has(record.state)) continue
      record.state = "TASK_STATE_FAILED"
      record.message = RESTART_MESSAGE
      if (record.states !== undefined && record.states.at(-1) !== "TASK_STATE_FAILED")
        record.states = [...record.states, "TASK_STATE_FAILED"]
      record.updatedAt = now()
      changed = true
    }
    if (changed) schedule()
  }

  return {
    attach: (base, ctx) => {
      const wrapped = (type: string, properties: Record<string, unknown>) => {
        base(type as never, properties as never)
        observe(type, properties, ctx)
      }
      return wrapped as unknown as A2AEventEmitter
    },
    setSession: (taskId, sessionId) => {
      const record = records.get(taskId)
      if (record === undefined) return
      record.sessionId = sessionId
      record.updatedAt = now()
      schedule()
    },
    list: () => [...records.values()].sort((a, b) => b.updatedAt - a.updatedAt),
    get: (taskId) => records.get(taskId),
    load: async () => {
      // A missing or malformed file is an empty registry: the plugin must still
      // start when its state file is corrupt.
      const text = await readFile(input.file, "utf8").catch(() => undefined)
      if (text !== undefined && text.trim() !== "") await restore(text)
    },
    flush: () => pending,
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

/** @jsxImportSource @opentui/solid */

// A2A panel (A2A-016). Everything here goes through the loopback control API
// — the TUI target never imports server-side modules — and renders the
// existing a2a.* bus events live. Until the A2A-014 control plane lands,
// demo/control-stub.ts serves the same contract in front of a real loopback
// peer (OPENCODE_A2A_ADMIN_URL).

import { For, Show, createEffect, createMemo, createSignal, onCleanup, type JSX } from "solid-js"
import { useTerminalDimensions } from "@opentui/solid"
import { TextAttributes, type ScrollBoxRenderable } from "@opentui/core"
import type {
  TuiDialogSelectOption,
  TuiPlugin,
  TuiPluginApi,
  TuiPluginModule,
} from "@opencode-ai/plugin/tui"
import {
  A2ATaskEventPropertiesSchema,
  A2ATurnEventPropertiesSchema,
  type Artifact,
  type TaskState,
} from "a2a"
import {
  ControlError,
  createControl,
  resolveControl,
  type A2AControl,
  type ControlPeer,
  type ControlSession,
  type ControlTurn,
  type PeersInfo,
} from "./control.ts"
import {
  artifactText,
  canCancel,
  canContinue,
  directionMark,
  formatAge,
  isCapMessage,
  mergePeers,
  sessionPeer,
  shortId,
  sortSessions,
  stateLabel,
  stateTone,
  turnText,
  type StateTone,
} from "./format.ts"

const POLL_MS = 2500

type LiveTask = { state?: TaskState; content?: string; artifact?: Artifact }

type Panel = {
  api: TuiPluginApi
  control(): Promise<A2AControl | undefined>
  reset(): void
  // Bumped on every a2a.* bus event; views refetch/rerender off it.
  revision(): number
  turns(taskId: string): readonly ControlTurn[]
  seed(taskId: string, turns: readonly ControlTurn[]): void
  live(taskId: string): LiveTask | undefined
  prompt(props: {
    title: string
    description?: () => JSX.Element
    placeholder?: string
  }): Promise<string | undefined>
  confirm(title: string, message: string): Promise<boolean>
  choose<T>(title: string, options: TuiDialogSelectOption<T>[]): Promise<T | undefined>
  busy(title: string, text: string): void
  toast(message: string, variant?: "info" | "success" | "warning" | "error"): void
  showSessions(): void
  showPeers(): void
  showThread(taskId: string): void
  startFlow(): void
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message
  return String(error)
}

function toneColor(api: TuiPluginApi, tone: StateTone) {
  const theme = api.theme.current
  switch (tone) {
    case "success":
      return theme.success
    case "warning":
      return theme.warning
    case "error":
      return theme.error
    case "muted":
      return theme.textMuted
    default:
      return theme.primary
  }
}

function Hints(props: { api: TuiPluginApi; items: readonly (readonly [string, string])[] }) {
  const theme = props.api.theme.current
  return (
    <box flexDirection="row" gap={2} paddingLeft={2} paddingRight={2}>
      <For each={props.items}>
        {(item) => (
          <text>
            <span style={{ fg: theme.text }}>{item[0]}</span>
            <span style={{ fg: theme.textMuted }}> {item[1]}</span>
          </text>
        )}
      </For>
    </box>
  )
}

function Notice(props: { api: TuiPluginApi; title: string; message: string }) {
  const theme = props.api.theme.current
  return (
    <box flexDirection="column" gap={1} paddingLeft={2} paddingRight={2} paddingBottom={1}>
      <box flexDirection="row" justifyContent="space-between">
        <text attributes={TextAttributes.BOLD} fg={theme.text}>
          {props.title}
        </text>
        <text fg={theme.textMuted} onMouseUp={() => props.api.ui.dialog.clear()}>
          esc
        </text>
      </box>
      <text fg={theme.textMuted}>{props.message}</text>
    </box>
  )
}

function BusyView(props: { panel: Panel; title: string; text: string }) {
  const theme = props.panel.api.theme.current
  return (
    <box flexDirection="column" gap={1} paddingLeft={2} paddingRight={2} paddingBottom={1}>
      <text attributes={TextAttributes.BOLD} fg={theme.text}>
        {props.title}
      </text>
      <text fg={theme.textMuted}>{props.text}</text>
    </box>
  )
}

type SessionRow = { kind: "session"; session: ControlSession } | { kind: "new" } | { kind: "peers" }

function SessionsView(props: { panel: Panel }) {
  const api = props.panel.api
  const theme = api.theme.current
  const [sessions, setSessions] = createSignal<ControlSession[]>([])
  const [status, setStatus] = createSignal<"loading" | "ready" | "unavailable" | "error">("loading")
  const [error, setError] = createSignal("")

  api.ui.dialog.setSize("large")

  const refresh = async () => {
    const ctl = await props.panel.control()
    if (!ctl) {
      setStatus("unavailable")
      return
    }
    try {
      setSessions(sortSessions(await ctl.sessions()))
      setStatus("ready")
    } catch (cause) {
      props.panel.reset()
      setStatus("error")
      setError(errorMessage(cause))
    }
  }

  createEffect(() => {
    props.panel.revision()
    void refresh()
  })
  const timer = setInterval(() => void refresh(), POLL_MS)
  onCleanup(() => clearInterval(timer))

  const rows = createMemo<TuiDialogSelectOption<SessionRow>[]>(() => [
    ...sessions().map((session) => ({
      title: `${directionMark(session.direction)} ${sessionPeer(session)}`,
      value: { kind: "session", session } as SessionRow,
      category: "Sessions",
      description: [
        shortId(session.taskId),
        `${session.turns ?? "-"} turns`,
        formatAge(session.updatedAt ?? session.createdAt),
      ]
        .filter((part) => part)
        .join(" · "),
      footer: (
        <span style={{ fg: toneColor(api, stateTone(session.state)) }}>{stateLabel(session.state, session.direction)}</span>
      ),
    })),
    {
      title: "New conversation",
      value: { kind: "new" },
      category: "Actions",
      description: "start a task with a configured peer",
    },
    {
      title: "Manage peers",
      value: { kind: "peers" },
      category: "Actions",
      description: "view, add, remove, and test allowedPeers",
    },
  ])

  const pick = (option: TuiDialogSelectOption<SessionRow>) => {
    if (option.value.kind === "new") return props.panel.startFlow()
    if (option.value.kind === "peers") return props.panel.showPeers()
    props.panel.showThread(option.value.session.taskId)
  }

  // Top-level must be an intrinsic: dialog.replace thunks are unrolled in a
  // tracked scope, and a component/accessor return value would re-track our
  // signals there — every state change would remount the whole view.
  return (
    <box flexDirection="column" flexGrow={1}>
      <Show
        when={status() === "ready"}
        fallback={
          <Notice
            api={api}
            title="A2A sessions"
            message={
              status() === "loading"
                ? "Loading sessions…"
                : status() === "unavailable"
                  ? "A2A control API not reachable. Enable the a2a plugin so its admin endpoint runs, or point OPENCODE_A2A_ADMIN_URL at demo/control-stub.ts."
                  : `A2A control API error: ${error()}`
            }
          />
        }
      >
        <api.ui.DialogSelect
          title="A2A sessions"
          placeholder="Filter sessions"
          options={rows()}
          onSelect={pick}
        />
        <Show when={sessions().length === 0}>
          <box paddingLeft={4}>
            <text fg={theme.textMuted}>No sessions yet — select “New conversation” to start one.</text>
          </box>
        </Show>
        <Hints
          api={api}
          items={[
            ["enter", "open"],
            ["esc", "close"],
          ]}
        />
      </Show>
    </box>
  )
}

type PeerRow = { kind: "peer"; peer: ControlPeer } | { kind: "add" } | { kind: "back" }

function PeersView(props: { panel: Panel }) {
  const api = props.panel.api
  const theme = api.theme.current
  const [info, setInfo] = createSignal<PeersInfo>()
  const [status, setStatus] = createSignal<"loading" | "ready" | "unavailable" | "error">("loading")
  const [error, setError] = createSignal("")

  api.ui.dialog.setSize("large")

  const refresh = async () => {
    const ctl = await props.panel.control()
    if (!ctl) {
      setStatus("unavailable")
      return
    }
    try {
      setInfo(await ctl.peers())
      setStatus("ready")
    } catch (cause) {
      props.panel.reset()
      setStatus("error")
      setError(errorMessage(cause))
    }
  }
  createEffect(() => {
    props.panel.revision()
    void refresh()
  })

  const rows = createMemo<TuiDialogSelectOption<PeerRow>[]>(() => [
    ...(info()?.peers ?? []).map((peer) => ({
      title: peer.name,
      value: { kind: "peer", peer } as PeerRow,
      category: "Peers",
      description: peer.url,
    })),
    { title: "Add peer", value: { kind: "add" } as PeerRow, category: "Actions", description: "add an allowedPeers entry" },
    { title: "Back to sessions", value: { kind: "back" } as PeerRow, category: "Actions" },
  ])

  const pick = (option: TuiDialogSelectOption<PeerRow>) => {
    if (option.value.kind === "add") return void addFlow()
    if (option.value.kind === "back") return props.panel.showSessions()
    void peerMenu(option.value.peer)
  }

  const writable = () => info()?.writable !== false

  const blocked = () => {
    props.panel.toast(
      info()?.hint ?? "allowedPeers is not editable through this endpoint — edit opencode.json by hand.",
      "warning",
    )
    props.panel.showPeers()
  }

  const addFlow = async () => {
    if (!writable()) return blocked()
    const name = (
      await props.panel.prompt({
        title: "New peer",
        placeholder: "name (local label)",
        description: () => (
          <text fg={theme.textMuted}>The local label for this peer — their agent-card name may differ.</text>
        ),
      })
    )?.trim()
    if (!name) return props.panel.showPeers()
    const url = (await props.panel.prompt({ title: `URL for ${name}`, placeholder: "http://host:port" }))?.trim()
    if (!url) return props.panel.showPeers()
    try {
      new URL(url)
    } catch {
      props.panel.toast(`Invalid URL for peer "${name}": ${url}`, "error")
      return props.panel.showPeers()
    }
    const ctl = await props.panel.control()
    if (!ctl) return props.panel.showPeers()
    props.panel.busy("Add peer", `Saving ${name}…`)
    try {
      await ctl.addPeer(name, url)
      props.panel.toast(`Added peer ${name}`, "success")
    } catch (cause) {
      props.panel.toast(errorMessage(cause), "error")
    }
    props.panel.showPeers()
  }

  const peerMenu = async (peer: ControlPeer) => {
    const action = await props.panel.choose(`Peer ${peer.name}`, [
      { title: "Test", value: "test" as const, description: "fetch the peer's agent card" },
      { title: "Remove", value: "remove" as const, description: `delete ${peer.name} from allowedPeers` },
      { title: "Back", value: "back" as const },
    ])
    if (!action || action === "back") return props.panel.showPeers()
    const ctl = await props.panel.control()
    if (!ctl) return props.panel.showPeers()
    if (action === "test") {
      props.panel.busy("Test peer", `Fetching agent card from ${peer.name}…`)
      try {
        const result = await ctl.testPeer(peer.name)
        props.panel.toast(`${peer.name} claims “${result.name}”`, "success")
      } catch (cause) {
        props.panel.toast(errorMessage(cause), "error")
      }
      return props.panel.showPeers()
    }
    if (!writable()) return blocked()
    const ok = await props.panel.confirm("Remove peer", `Remove ${peer.name} (${peer.url}) from allowedPeers?`)
    if (!ok) return props.panel.showPeers()
    props.panel.busy("Remove peer", `Removing ${peer.name}…`)
    try {
      await ctl.removePeer(peer.name)
      props.panel.toast(`Removed peer ${peer.name}`, "success")
    } catch (cause) {
      props.panel.toast(errorMessage(cause), "error")
    }
    props.panel.showPeers()
  }

  const self = () => {
    const own = info()?.self
    if (!own) return
    const listen = own.port === undefined ? "not listening" : `listening :${own.port}`
    return `you: ${own.name ?? "unnamed"} · ${listen}`
  }

  return (
    <box flexDirection="column" flexGrow={1}>
      <Show
        when={status() === "ready"}
        fallback={
          <Notice
            api={api}
            title="A2A peers"
            message={
              status() === "loading"
                ? "Loading peers…"
                : status() === "unavailable"
                  ? "A2A control API not reachable."
                  : `A2A control API error: ${error()}`
            }
          />
        }
      >
        <api.ui.DialogSelect title="A2A peers" placeholder="Filter peers" options={rows()} onSelect={pick} />
        <box paddingLeft={4} flexDirection="column">
          <Show when={self()}>{(label) => <text fg={theme.textMuted}>{label()}</text>}</Show>
          <Show when={!writable()}>
            <text fg={theme.textMuted}>{info()?.hint ?? "peers are read-only here"}</text>
          </Show>
        </box>
        <Hints
          api={api}
          items={[
            ["enter", "select"],
            ["esc", "close"],
          ]}
        />
      </Show>
    </box>
  )
}

function ThreadView(props: { panel: Panel; taskId: string }) {
  const api = props.panel.api
  const theme = api.theme.current
  const size = useTerminalDimensions()
  const [session, setSession] = createSignal<ControlSession>()
  const [status, setStatus] = createSignal<"loading" | "ready" | "missing" | "error">("loading")
  const [error, setError] = createSignal("")
  let box: ScrollBoxRenderable | undefined

  api.ui.dialog.setSize("xlarge")

  const refresh = async () => {
    const ctl = await props.panel.control()
    if (!ctl) {
      setStatus("missing")
      setError("A2A control API not reachable.")
      return
    }
    try {
      const detail = await ctl.session(props.taskId)
      setSession(detail.session)
      props.panel.seed(props.taskId, detail.turns)
      setStatus("ready")
    } catch (cause) {
      if (cause instanceof ControlError && cause.status === 404) {
        setStatus("missing")
        setError(`Task ${shortId(props.taskId)} is no longer in the registry.`)
        return
      }
      props.panel.reset()
      setStatus("error")
      setError(errorMessage(cause))
    }
  }

  createEffect(() => {
    props.panel.revision()
    void refresh()
  })
  const timer = setInterval(() => void refresh(), POLL_MS)
  onCleanup(() => clearInterval(timer))

  const state = () => props.panel.live(props.taskId)?.state ?? session()?.state ?? "TASK_STATE_UNSPECIFIED"
  const replyable = () => canContinue(state()) && session()?.direction === "outbound"
  const liveContent = () => props.panel.live(props.taskId)?.content ?? session()?.message
  const artifact = () => props.panel.live(props.taskId)?.artifact ?? session()?.artifact
  const turns = () => props.panel.turns(props.taskId)

  const sendReply = async () => {
    const text = (await props.panel.prompt({ title: `Reply · ${shortId(props.taskId)}`, placeholder: "message" }))?.trim()
    const ctl = await props.panel.control()
    if (!text || !ctl) return props.panel.showThread(props.taskId)
    props.panel.busy("A2A task", "Sending…")
    try {
      await ctl.reply(props.taskId, text)
    } catch (cause) {
      props.panel.toast(errorMessage(cause), "error")
    }
    props.panel.showThread(props.taskId)
  }

  const cancelTask = async () => {
    const ok = await props.panel.confirm(
      "Cancel task",
      `Cancel task ${shortId(props.taskId)} with ${session()?.peerId ?? "peer"}?`,
    )
    if (!ok) return props.panel.showThread(props.taskId)
    const ctl = await props.panel.control()
    if (!ctl) return props.panel.showThread(props.taskId)
    try {
      await ctl.cancel(props.taskId)
      props.panel.toast("Task canceled", "success")
    } catch (cause) {
      props.panel.toast(errorMessage(cause), "error")
    }
    props.panel.showThread(props.taskId)
  }

  onCleanup(
    api.keymap.registerLayer({
      bindings: [
        { key: "m", desc: "Reply", group: "A2A", cmd: () => { if (replyable()) void sendReply() } },
        { key: "return", desc: "Reply", group: "A2A", cmd: () => { if (replyable()) void sendReply() } },
        {
          key: "x",
          desc: "Cancel task",
          group: "A2A",
          cmd: () => {
            if (canCancel(state())) void cancelTask()
          },
        },
        { key: "r", desc: "Refresh", group: "A2A", cmd: () => void refresh() },
        { key: "b", desc: "Back to sessions", group: "A2A", cmd: () => props.panel.showSessions() },
        { key: "backspace", desc: "Back to sessions", group: "A2A", cmd: () => props.panel.showSessions() },
        { key: "up", desc: "Scroll up", group: "A2A", cmd: () => box?.scrollBy(-1) },
        { key: "down", desc: "Scroll down", group: "A2A", cmd: () => box?.scrollBy(1) },
        { key: "pageup", desc: "Page up", group: "A2A", cmd: () => box?.scrollBy(-10) },
        { key: "pagedown", desc: "Page down", group: "A2A", cmd: () => box?.scrollBy(10) },
      ],
    }),
  )

  return (
    <box flexDirection="column" gap={1} paddingBottom={1}>
      <box flexDirection="row" justifyContent="space-between" paddingLeft={2} paddingRight={2}>
        <text attributes={TextAttributes.BOLD} fg={theme.text}>
          <Show when={session()} fallback="A2A task">
            {(item) => `${directionMark(item().direction)} ${sessionPeer(item())}`}
          </Show>
          <span style={{ fg: theme.textMuted }}> · {shortId(props.taskId)}</span>
        </text>
        <text fg={theme.textMuted} onMouseUp={() => api.ui.dialog.clear()}>
          esc
        </text>
      </box>
      <box flexDirection="row" gap={2} paddingLeft={2} paddingRight={2}>
        <text fg={toneColor(api, stateTone(state()))}>{stateLabel(state(), session()?.direction)}</text>
        <Show when={isCapMessage(liveContent())}>
          <text fg={theme.textMuted}>{liveContent()}</text>
        </Show>
      </box>
      <Show
        when={status() === "ready"}
        fallback={
          <box paddingLeft={2} paddingRight={2}>
            <text fg={theme.textMuted}>{status() === "loading" ? "Loading task…" : error()}</text>
          </box>
        }
      >
        <scrollbox
          flexGrow={1}
          maxHeight={Math.max(6, Math.floor(size().height * 0.55))}
          stickyScroll={true}
          stickyStart="bottom"
          paddingLeft={2}
          paddingRight={2}
          ref={(r: ScrollBoxRenderable) => (box = r)}
        >
          <For each={turns()} fallback={<text fg={theme.textMuted}>Waiting for the first turn…</text>}>
            {(turn, index) => (
              <box flexDirection="column" marginBottom={1}>
                <text>
                  <Show
                    when={turn.speaker === "local"}
                    fallback={
                      <span style={{ fg: theme.primary, attributes: TextAttributes.BOLD }}>
                        {turn.peerId ?? session()?.peerId ?? "peer"}
                      </span>
                    }
                  >
                    <span style={{ fg: theme.success, attributes: TextAttributes.BOLD }}>you</span>
                  </Show>
                  <span style={{ fg: theme.textMuted }}> · turn {turn.index ?? index()}</span>
                </text>
                <text fg={theme.text} wrapMode="word">
                  {turnText(turn)}
                </text>
              </box>
            )}
          </For>
        </scrollbox>
        <Show when={artifactText(artifact())}>
          {(verdict) => (
            <box flexDirection="column" paddingLeft={2} paddingRight={2}>
              <text fg={theme.warning} attributes={TextAttributes.BOLD}>
                verdict
              </text>
              <text fg={theme.text} wrapMode="word">
                {verdict()}
              </text>
            </box>
          )}
        </Show>
      </Show>
      <Hints
        api={api}
        items={
          status() === "ready"
            ? [
                ...(replyable() ? ([["m", "reply"]] as const) : []),
                ...(canCancel(state()) ? ([["x", "cancel"]] as const) : []),
                ["b", "sessions"],
                ["r", "refresh"],
                ["esc", "close"],
              ]
            : [["esc", "close"]]
        }
      />
    </box>
  )
}

const tui: TuiPlugin = async (api) => {
  let pending: Promise<A2AControl | undefined> | undefined

  const control = () => {
    pending ??= resolveControl({
      env: process.env,
      // The generated SDK keeps the client's base URL private; read it
      // anyway — the control API may be hosted on the opencode server.
      serverUrl: (api.client as unknown as { client?: { getConfig?: () => { baseUrl?: string } } }).client
        ?.getConfig?.().baseUrl,
      directories: [...new Set([api.state.path.worktree, api.state.path.directory].filter(Boolean))],
    }).then((found) => (found ? createControl(found.base) : undefined))
    return pending
  }
  const reset = () => {
    pending = undefined
  }

  const [revision, setRevision] = createSignal(0)
  const bump = () => setRevision((value) => value + 1)

  const turnsByTask = new Map<string, ControlTurn[]>()
  const liveByTask = new Map<string, LiveTask>()

  // The generated SDK's Event union does not know the plugin's a2a.* types,
  // but the bus carries any { type, properties } payload.
  const on = api.event.on as unknown as (
    type: string,
    handler: (event: { type: string; properties?: unknown }) => void,
  ) => () => void

  const unsubs = [
    on("a2a.conversation.turn", (event) => {
      const parsed = A2ATurnEventPropertiesSchema.safeParse(event.properties)
      if (!parsed.success || !parsed.data.taskId) return
      const taskId = parsed.data.taskId
      const turn: ControlTurn = {
        index: parsed.data.turn,
        speaker: parsed.data.speaker,
        peerId: parsed.data.peerId,
        content: parsed.data.content,
      }
      const list = [...(turnsByTask.get(taskId) ?? [])]
      const found = turn.index === undefined ? -1 : list.findIndex((item) => item.index === turn.index)
      if (found >= 0) {
        if (turnText(list[found]) === turnText(turn)) return
        list[found] = turn
      } else {
        list.push(turn)
      }
      list.sort((a, b) => (a.index ?? 0) - (b.index ?? 0))
      turnsByTask.set(taskId, list)
      bump()
    }),
    ...["a2a.task.dispatched", "a2a.task.updated", "a2a.task.completed", "a2a.task.failed"].map((type) =>
      on(type, (event) => {
        const parsed = A2ATaskEventPropertiesSchema.safeParse(event.properties)
        if (!parsed.success) return
        liveByTask.set(parsed.data.taskId, {
          state: parsed.data.state,
          content: parsed.data.content,
          artifact: parsed.data.artifact,
        })
        bump()
      }),
    ),
  ]
  for (const unsub of unsubs) api.lifecycle.onDispose(unsub)

  function startFlow() {
    void (async () => {
      const ctl = await control()
      if (!ctl) {
        api.ui.dialog.replace(() => (
          <Notice
            api={api}
            title="A2A: new conversation"
            message="A2A control API not reachable. Enable the a2a plugin so its admin endpoint runs, or point OPENCODE_A2A_ADMIN_URL at demo/control-stub.ts."
          />
        ))
        return
      }
      panel.busy("A2A: new conversation", "Loading peers…")
      let peers: PeersInfo
      let sessions: ControlSession[]
      try {
        ;[peers, sessions] = await Promise.all([ctl.peers(), ctl.sessions()])
      } catch (cause) {
        reset()
        panel.toast(errorMessage(cause), "error")
        return panel.showSessions()
      }
      const merged = mergePeers(peers.peers, sessions)
      if (merged.length === 0) {
        api.ui.dialog.replace(() => (
          <Notice
            api={api}
            title="A2A: new conversation"
            message={peers.hint ?? "No peers configured — add one under A2A: Peers first."}
          />
        ))
        return
      }
      const peer = await panel.choose(
        "A2A: new conversation",
        merged.map((entry) => ({
          title: entry.name,
          value: entry,
          description: entry.url ?? "seen in sessions · no URL — add one under A2A: Peers",
        })),
      )
      if (!peer) return panel.showSessions()
      if (!peer.url) {
        panel.toast(`${peer.name} has no URL — add one under A2A: Peers.`, "warning")
        return panel.showPeers()
      }
      const text = (
        await panel.prompt({
          title: `Message to ${peer.name}`,
          placeholder: "What should the peer work on?",
          description: () => (
            <text fg={api.theme.current.textMuted}>{peer.url} · runs to the turn cap unless it finishes early.</text>
          ),
        })
      )?.trim()
      if (!text) return panel.showSessions()
      panel.busy("A2A: new conversation", `Starting with ${peer.name}…`)
      try {
        const result = await ctl.start(peer.name, text)
        if (result.taskId) return panel.showThread(result.taskId)
        panel.toast("The peer did not create a task", "error")
        panel.showSessions()
      } catch (cause) {
        panel.toast(errorMessage(cause), "error")
        panel.showSessions()
      }
    })()
  }

  // Tracks which panel view owns the dialog stack so the shortcut can toggle
  // it closed. replace() runs the previous item's onClose, clearing `open`
  // whenever a different dialog takes over.
  let open: "sessions" | "peers" | "thread" | undefined
  const openView = (kind: NonNullable<typeof open>, view: () => JSX.Element) => {
    api.ui.dialog.replace(view, () => {
      if (open === kind) open = undefined
    })
    open = kind
  }

  const panel: Panel = {
    api,
    control,
    reset,
    revision,
    turns: (taskId) => {
      revision()
      return turnsByTask.get(taskId) ?? []
    },
    live: (taskId) => {
      revision()
      return liveByTask.get(taskId)
    },
    seed: (taskId, fetched) => {
      // Merge event-fed turns the fetch has not caught up to yet, and only
      // bump when content changed so the refetch effect cannot loop.
      const merged = [
        ...fetched,
        ...(turnsByTask.get(taskId) ?? []).filter(
          (turn) => turn.index !== undefined && !fetched.some((item) => item.index === turn.index),
        ),
      ].sort((a, b) => (a.index ?? 0) - (b.index ?? 0))
      const prev = turnsByTask.get(taskId) ?? []
      const same =
        merged.length === prev.length &&
        merged.every(
          (turn, index) =>
            turn.index === prev[index].index &&
            turn.speaker === prev[index].speaker &&
            turn.peerId === prev[index].peerId &&
            turnText(turn) === turnText(prev[index]),
        )
      if (same) return
      turnsByTask.set(taskId, merged)
      bump()
    },
    prompt: (props) =>
      new Promise<string | undefined>((resolve) => {
        api.ui.dialog.replace(
          () => (
            <api.ui.DialogPrompt
              title={props.title}
              placeholder={props.placeholder}
              description={props.description}
              onConfirm={(value) => resolve(value)}
            />
          ),
          () => resolve(undefined),
        )
      }),
    confirm: (title, message) =>
      new Promise<boolean>((resolve) => {
        api.ui.dialog.replace(
          () => (
            <api.ui.DialogConfirm
              title={title}
              message={message}
              onConfirm={() => resolve(true)}
              onCancel={() => resolve(false)}
            />
          ),
          () => resolve(false),
        )
      }),
    choose: (title, options) =>
      new Promise((resolve) => {
        api.ui.dialog.replace(
          () => <api.ui.DialogSelect title={title} options={options} onSelect={(option) => resolve(option.value)} />,
          () => resolve(undefined),
        )
      }),
    busy: (title, text) => api.ui.dialog.replace(() => <BusyView panel={panel} title={title} text={text} />),
    toast: (message, variant = "info") => api.ui.toast({ message, variant }),
    showSessions: () => {
      if (open === "sessions") {
        api.ui.dialog.clear()
        return
      }
      openView("sessions", () => <SessionsView panel={panel} />)
    },
    showPeers: () => {
      if (open === "peers") {
        api.ui.dialog.clear()
        return
      }
      openView("peers", () => <PeersView panel={panel} />)
    },
    showThread: (taskId) => openView("thread", () => <ThreadView panel={panel} taskId={taskId} />),
    startFlow,
  }

  api.lifecycle.onDispose(
    api.keymap.registerLayer({
      commands: [
        {
          name: "a2a.new",
          title: "A2A: New conversation",
          category: "A2A",
          namespace: "palette",
          slashName: "a2a-new",
          run: () => panel.startFlow(),
        },
        {
          name: "a2a.sessions",
          title: "A2A: Sessions",
          category: "A2A",
          namespace: "palette",
          slashName: "a2a",
          run: () => panel.showSessions(),
        },
        {
          name: "a2a.peers",
          title: "A2A: Peers",
          category: "A2A",
          namespace: "palette",
          slashName: "a2a-peers",
          run: () => panel.showPeers(),
        },
      ],
      bindings: api.tuiConfig.keybinds.gather("a2a.palette", ["a2a.new", "a2a.sessions", "a2a.peers"]),
    }),
  )
}

const plugin: TuiPluginModule = {
  id: "a2a",
  tui,
}

export default plugin
